function solve(ops, args) {
  const cap = args[0][0];
  const map = new Map();
  const order = [];
  const out = [];
  const touch = (k) => {
    const i = order.indexOf(k);
    if (i >= 0) order.splice(i, 1);
    order.push(k);
  };
  for (let i = 1; i < ops.length; i++) {
    const op = ops[i];
    const a = args[i];
    if (op === 'put') {
      const [k, v] = a;
      map.set(k, v);
      touch(k);
      if (map.size > cap) {
        const oldest = order.shift();
        map.delete(oldest);
      }
      out.push(null);
    } else {
      const k = a[0];
      if (!map.has(k)) out.push(-1);
      else { touch(k); out.push(map.get(k)); }
    }
  }
  return out;
}
